        ShardableType::PersistentISet(_) => None,
        ShardableType::PersistentMap(_, _) => None,
        ShardableType::PersistentIMap(_, _) => None,
        ShardableType::PersistentCount => None,
        ShardableType::PersistentBool => None,
        ShardableType::Count => None,
